package shopee
import("context";"encoding/json";"strconv";"time";shopeesdk "github.com/openoms-org/openoms/packages/shopee-go-sdk")
type OrderSnapshot struct{OrderSN,Status,BuyerUsername,Currency,PaymentMethod string;TotalAmount float64;CreatedAt time.Time;Items []OrderItemSnapshot;ShippingAddress json.RawMessage}
type OrderItemSnapshot struct{ItemID,ModelID,ItemSKU,ModelSKU,Name string;Quantity int;UnitPrice float64}
func(p *Provider)ReadOrders(ctx context.Context,from,to time.Time,cursor,status string)([]OrderSnapshot,string,bool,error){l,err:=p.client.GetOrderList(ctx,p.creds.AccessToken,p.creds.ShopID,"update_time",from.Unix(),to.Unix(),50,cursor,status);if err!=nil{return nil,"",false,err};sns:=make([]string,len(l.OrderList));for i,o:=range l.OrderList{sns[i]=o.OrderSN};if len(sns)==0{return nil,l.NextCursor,l.More,nil};d,err:=p.client.GetOrderDetail(ctx,p.creds.AccessToken,p.creds.ShopID,sns);if err!=nil{return nil,"",false,err};out:=make([]OrderSnapshot,0,len(d));for _,o:=range d{addr,_:=json.Marshal(o.RecipientAddress);s:=OrderSnapshot{OrderSN:o.OrderSN,Status:o.OrderStatus,BuyerUsername:o.BuyerUsername,Currency:o.Currency,PaymentMethod:o.PaymentMethod,TotalAmount:o.TotalAmount,CreatedAt:time.Unix(o.CreateTime,0).UTC(),ShippingAddress:addr};for _,it:=range o.ItemList{s.Items=append(s.Items,OrderItemSnapshot{ItemID:strconv.FormatInt(it.ItemID,10),ModelID:strconv.FormatInt(it.ModelID,10),ItemSKU:it.ItemSKU,ModelSKU:it.ModelSKU,Name:it.ItemName,Quantity:it.ModelQuantityPurchased,UnitPrice:it.ModelDiscountedPrice})};out=append(out,s)};return out,l.NextCursor,l.More,nil}
